// One report per business, to each of its alert numbers and its alert email:
// what the bot handled in the last 24 hours and who is still waiting on the team.
const clients = $('Get Clients').all().map((i) => i.json).filter((c) => c.client_id && c.daily_summary !== false);
const events = $input.all().map((i) => i.json).filter((e) => e && e.client_id);
const out = [];
for (const c of clients) {
  const mine = events.filter((e) => e.client_id === c.client_id);
  const count = (k) => mine.filter((e) => e.kind === k).length;
  const people = (k) => {
    const seen = new Set();
    return mine.filter((e) => e.kind === k && !seen.has(e.phone) && seen.add(e.phone))
      .slice(0, 10).map((e) => `• ${e.name ? e.name + ' ' : ''}+${e.phone} — https://wa.me/${e.phone}`);
  };
  const biz = c.business_name || c.client_id;
  const leads = people('lead');
  const waiting = people('human');
  const text = [
    `📊 *${biz} · Daily WhatsApp report*`,
    '━━━━━━━━━━━━━━',
    `🆕 New contacts: *${count('new_contact')}*`,
    `💼 Leads: *${count('lead')}*`,
    `🙋 Asked for a person: *${count('human')}*`,
    `⚠️ Couldn't answer: *${count('unanswered')}*`,
    `🛒 Sales: *${count('sale')}* · 📥 Restocks: *${count('restock')}*`,
    leads.length ? ['', '*Leads to follow up*', ...leads].join('\n') : null,
    waiting.length ? ['', '*Wanted a person*', ...waiting].join('\n') : null,
    mine.length ? null : '\n_A quiet day — no new activity._',
    '━━━━━━━━━━━━━━',
  ].filter((l) => l !== null).join('\n');
  let alerts = c.alert_numbers;
  if (typeof alerts === 'string') { try { alerts = JSON.parse(alerts); } catch (e) { alerts = [alerts]; } }
  // The first copy of each business's report also carries its email, so the
  // same report goes to the inbox once (Email Summaries).
  const email = String(c.alert_email || '').trim();
  const subject = `📊 ${biz} · Daily WhatsApp report`;
  [...new Set((alerts || []).map(String))].filter(Boolean)
    .forEach((n, i) => out.push({ json: { number: n, instance: c.instance_name, text, email: i === 0 ? email : '', subject } }));
}
return out;
